-- Test SQL file for poste exec-file feature (1000+ lines)
-- Pure SQL, no poste-specific directives. Connection is provided via CLI --connection.

CREATE TABLE IF NOT EXISTS poste_test_users (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL,
    age INT DEFAULT 0,
    score DOUBLE DEFAULT 0.0,
    active INT DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS poste_test_events (
    id INT PRIMARY KEY AUTO_INCREMENT,
    user_id INT NOT NULL,
    event_type VARCHAR(50) NOT NULL,
    value DOUBLE DEFAULT 0.0,
    metadata TEXT,
    occurred_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES poste_test_users(id)
);

CREATE TABLE IF NOT EXISTS poste_test_metrics (
    id INT PRIMARY KEY AUTO_INCREMENT,
    metric_name VARCHAR(100) NOT NULL,
    metric_value DOUBLE NOT NULL,
    recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

