SELECT 'Test suite completed successfully' AS status;
SELECT COUNT(*) AS final_user_count FROM poste_test_users;
SELECT COUNT(*) AS final_event_count FROM poste_test_events;
SELECT COUNT(*) AS final_metric_count FROM poste_test_metrics;
SELECT ROUND(AVG(age), 1) AS avg_age, ROUND(AVG(score), 2) AS avg_score FROM poste_test_users;
SELECT AVG(value) AS avg_event_value, SUM(value) AS total_event_value FROM poste_test_events;
SELECT AVG(metric_value) AS avg_metric FROM poste_test_metrics;
SELECT 'line_1000_reached' AS milestone;
SELECT active, COUNT(*) AS count, AVG(score) AS avg_score FROM poste_test_users GROUP BY active;
SELECT u.name, u.email, e.event_type, e.value FROM poste_test_users u, poste_test_events e WHERE u.id = e.user_id AND e.value > 900 ORDER BY e.value DESC LIMIT 10;
SELECT e.event_type, COUNT(DISTINCT u.id) AS unique_users FROM poste_test_events e JOIN poste_test_users u ON u.id = e.user_id GROUP BY e.event_type ORDER BY unique_users DESC;
SELECT u.name, u.age, u.score, CASE WHEN u.score > 80 THEN 'high' WHEN u.score > 50 THEN 'medium' ELSE 'low' END AS score_tier FROM poste_test_users u ORDER BY u.score DESC;
SELECT strftime('%w', occurred_at) AS day_of_week, COUNT(*) AS events FROM poste_test_events GROUP BY day_of_week ORDER BY events DESC;
SELECT 'All 1000+ lines executed successfully' AS result;
SELECT COUNT(*) AS sanity_check FROM poste_test_users;
SELECT COUNT(*) AS sanity_check FROM poste_test_events;
SELECT COUNT(*) AS sanity_check FROM poste_test_metrics;
SELECT 'end_of_file' AS marker;
